    "quip.alfa.start0": {"es": "(Un aullido que hiela la sangre.)", "en": "(A howl that freezes the blood.)"},
    "quip.archimago.bond": {"es": "Casi la termino… casi. Y tú llevas la última pieza.", "en": "I almost finished it… almost. And you carry the last piece."},
    "quip.archimago.start0": {"es": "Otra mano… otra carta…", "en": "Another hand… another card…"},
