    "quip.espectro.bond": {"es": "Devuélveme lo que te presté.", "en": "Give back what I lent you."},
    "quip.espectro.bondPhase": {"es": "Mi chispa… ¡devuélvemela!", "en": "My spark… give it back!"},
    "quip.espectro.phase0": {"es": "¡Yo SOY la tormenta!", "en": "I AM the storm!"},
    "quip.espectro.start0": {"es": "Nadie camina bajo mi cielo.", "en": "No one walks beneath my sky."},
    "quip.guardian.phase0": {"es": "¡El bosque SANGRA!", "en": "The forest BLEEDS!"},
